WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (87::BIGINT, 'La otra opción para llevar este curso es Adrián y, no gracias. Y si sus clases son aburridas y largas, las evaluaciones no se entienden mucho, pero hay que esforzarse para quedarse. Solo vaya a clases, pregunte de vez en cuando y el profe se acuerda de eso cuando pone notas. Éxitos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'd126406d34c60809d51903a3e744d979039e05fb0abf6d3a1adc53aa17897126'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'Si tienen la oportunidad de llevar fluidos con él, desaprovéchenla. Nunca sube notas bien al tec digital, cuesta que revise las cosas, revisa demasiado duro y a veces ni explica el porque. Las clases demasiado largas y 0 didácticas, cuesta mucho entenderle.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, '97f989ce56ae47d63daec361a3192974b7329ae418a2356ab5cfa753cf1101ea'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'Había tenido una mala experiencia con él en otro curso, es aburrido y sus clases son largas pero se nota que sabe mucho y ha estado intentando mejorar como profesor.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2148b34a4039e422afb59405d0cec1ab251c6054d7a0d6789b6a4fa3cf99e4f5'::TEXT, ARRAY[2758, 2760, 2783]::BIGINT[]),
    (87::BIGINT, 'Si puede evitarlo para Fluidos, hágalo, es un curso muy duro, pero no ayuda mucho que él sea arrogante, califica duro y las tareas sean largas'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '053ae6c81a4e123d6e3d4a83fbebffd4ee57274945805a3664e582eb1cee241d'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'Ish mae, si tiene la oportunidad lleve con el otro profesor. Las clases son 4h de verlo desarrollando fórmulas. No explica ejercicios solo los copia. No se dignaba a darnos receso en una clase de 4h y si lo hacía nos lo contaba luego para salir más tarde. La verdad pésima experiencia.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ce9fecf0cb984ef8f5776381b0da27b663329923a138496933810175fb2b610e'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'Ser arrogante no lo hace ser buen profesor. Las clases son demostraciones de fórmulas, o sea , se va a perder el tiempo. No explica ejercicios, solo los trae en una hoja resultas y los copia en la pizarra y cree que con eso uno entiende. Lleven fluidos con el otro profe.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'bcfd606e2e81be6bf0b4631e63e229853a1f2cb925daf1a45430d7fe2aed9ee4'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'El profe habla tan lento que las clases se pueden ver bien bien a 2x, a pesar de que la clase es super pesada se nota que el profe trata de dejar todo lo más claro posible y se preocupa por darle al estudiante una vista de la aplicación del curso al campo laboral'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a2fae4adb8a6b39f50fa157ac6db93ec3a2e276915f8bf6f7fca5703e6aca14b'::TEXT, ARRAY[2758]::BIGINT[]),
    (87::BIGINT, 'Consigase un buen grupo para los examenes y tareas, la clase es algo pesada asi que preparese, es serio y habla con mucha paciencia, se usa mucho excel y es detallista revisando las cosas asi que cumpla bien lo que le pide. Si se aprende bastante'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1ed65a79d920c136fb54bf225afe7b066171b90bb079122c44b2f2bfa789e3ba'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'Es uno de los mejores profes de la escuela de materiales. Con el profe se aprende mucho, tanto a nivel académico como laboral. Las evaluaciones son un poco pesadas, pero totalmente logrables si se tiene un buen grupo de trabajo. Si puede, siempre matricule con él, no se arrepentirá.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '13523dde2323717e0b318fbdce711b741f53261c25397df1dbddd30ba4ab23a0'::TEXT, ARRAY[2758, 2760]::BIGINT[]),
    (87::BIGINT, 'El debería de fomentar un ambiente de aprendizaje sano, literal en sus clases da miedo decir algo; solo el tiene la razón y sino no es como el dice, no tiene ningún tipo de valor la opinion'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-13T00:00:00+00:00'::TIMESTAMPTZ, '892395a1b752f0d4509faeaf16db92d6d0293dc1d656cd4100ff68397acf41f4'::TEXT, ARRAY[2758, 2760]::BIGINT[]),
    (87::BIGINT, 'En virtual el curso se vuelve un poco más ligero. El mae es super serio. Matlab ni lo vuelven a ver, solo se usa excel. Califica un poco fuerte. Cumpla con todo lo que el profe le pide y sale bien. El profe cree que los trabajos en clase salen en una hora, pero ahí alcanza el tiempo. Si se aprende'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-12-24T00:00:00+00:00'::TIMESTAMPTZ, '5bb9ef5d4ce0b2013afb0dc23501bc6cfdbc44db0bfef9c0d8d4fd1537ec0557'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'No se entiende nada hasta que hace ejercicios. En modalidad virtual el curso fue muy sencillo. Es muy serio. Si hace los trabajos como él los pide, le va a ir bien.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '464d87480b33e6705ae5ed424a1ca88b31bc69f7934e1eb25a236b640317d904'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'Lqm, es súper buen profesional y profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7311d1b557d4718a150b0eeb11fe0ea16c804d79cb433ed8456405db2148d855'::TEXT, ARRAY[2758]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, '8d7b67f48a2ea0c0607047c3b4b3844c1e6dd75cffc3e4362cddf84ea46f8fd3'::TEXT, ARRAY[2758]::BIGINT[]),
    (87::BIGINT, 'Sabe demasiado y hace que las clases sean muy interesantes, le gustan los trabajos bien hechos y que se note el interés en el curso. Muy buen profesional'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b18f33595ca8a66c242b945feff6ab5cfb27dfadd9c5a7fbca312c5fd1b42845'::TEXT, ARRAY[2750]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6d13734fce6f4be32cbac2b13a6ea503c15f94b9cbd8ae4d3e82c1275e22f785'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'No se le entiende nada hasta que él da un ejemplo. Sólo trabaja en Excel y es demasiado serio. Evaluaciones accesibles si usted hace todo como él lo pide.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-25T00:00:00+00:00'::TIMESTAMPTZ, '93455dde7a9d2a8b9694d1f9f0dc04a86460ef318172145532aa3a9d2441e616'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'El curso no le llama mucho la atención, entonces sus clases son casi que recitar el Mott y la clase se vuelve aburrida. Eso sí, explica bien y da ejemplos claros sobre aplicaciones (eso es lo interesante del curso). Si le pone le va bien en los exámenes, porque los ejercicios los saca de un libro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '19e1a8ad8e34a43ee51aadef8f40aa781a619a92105f3d049a600f6169cb800d'::TEXT, ARRAY[2751]::BIGINT[]),
    (87::BIGINT, 'Llevar la práctica con él es lo mejor, se pone con uno hacerla. Lo ayuda a uno demasiado. Le monta los experimentos, corrige el trabajo y todo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-13T00:00:00+00:00'::TIMESTAMPTZ, '0a2fc157144d8fe74cb083d2d3ad751121dcff8813d8a96bd4a766886348e77e'::TEXT, ARRAY[2774]::BIGINT[]),
    (87::BIGINT, 'Es un buen profesor, un gran ingeniero y posee un gran dominio de la carrera de materiales. Pero procura no caerle mal, te puede convertir el semestre en un infierno. Y si le caíste bien, te va ir super bien. Procurá solo caerle regular para vivir en paz.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2017-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'c3e111db251e261017d5f7e080a66d123bba138542f75bab14ad2f3d021a8601'::TEXT, ARRAY[2758, 2783]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0a77d9972803727d4f40ab8ebe903c11d85bb1d4cb78d218de0f657f1a582bc1'::TEXT, ARRAY[2751]::BIGINT[]),
    (87::BIGINT, 'No deja muchas tareas, califica el trabajo en clase, los quices y exámenes son realmente sencillos. Explica muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '863505e31833241062c79af1bc69b7a61ccd751132c030fa0cfc3b51bde35ca1'::TEXT, ARRAY[968]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos exámenes']::TEXT[], '2016-12-31T00:00:00+00:00'::TIMESTAMPTZ, 'fa8aca18a0d619da4b856e6f0165921e663e96184fc4d126a4ae8624831f1433'::TEXT, ARRAY[2751]::BIGINT[]),
    (87::BIGINT, 'Demasiado bueno! Explica impecable, pero hay que estudiar bastante'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-10T00:00:00+00:00'::TIMESTAMPTZ, '78d64e7a4cca318387c77afb5f470be85c63214d12f52fcd995e00f94bbfab7f'::TEXT, ARRAY[2751]::BIGINT[]),
    (87::BIGINT, 'Explica muy bien, se toma su tiempo y escribe un "titulo" sobre que esta haciendo en cada paso para que uno entienda y sea mas facil estudiar. Evalua duro los quices, tareas y examenes, pero asi como evalua enseña. Un excelente profesor, duro, pero excelente'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-20T00:00:00+00:00'::TIMESTAMPTZ, '886a94c04cf140d2d466349a2921648cb1ddc2916db4163f93056cdf6524498d'::TEXT, ARRAY[2751]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a55fa6264db05ab8f066c1bbb8c0a3ce7aef743b455390352ff077180288e648'::TEXT, ARRAY[2758]::BIGINT[]),
    (87::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0f29419338b8693c35e707896d1d4cc904bb5c26c48296e039b2d1bd8a9e4183'::TEXT, ARRAY[2787]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
